from collections import defaultdict

def can_buy_dishes(n, m, prices, standards, beauties, incomes, preferences):
    dishes = defaultdict(list)
    for i, (p, s, b) in enumerate(zip(prices, standards, beauties)):
        dish = {
            'price': p,
            'standard': s,
            'beauty': b,
            'income': incomes,
            'preference': preferences
        }
        dishes[s].append(dish)

    # Sort dishes by price
    for s in dishes:
        dishes[s].sort()

    buys = [0] * m
    for b in range(1, 101):  # considering the upper limit for preference difference
        for price in range(1, 101):
            okay = True
            for dish in dishes[price]:
                if dish['income'] >= dish['preference'] + b:
                    okay = False
                    break
            if okay:
                for dish in dishes[price]:
                    if dish['beauty'] - dish['income'] + b <= 0:
                        buys[price - 1] += 1
                    else:
                        break

    return buys

