import itertools

def k_cover(edges, min_degree, n1, n2):
    degree_map = {i: 0 for i in range(1, n1*n2 + 1)}
    covered_edges = set()

    for u, v in sorted(edges, key=lambda x: x[0]):
        if degree_map[u] < min_degree or degree_map[v] < min_degree:
            covered_edges.add((u, v))
            current_degree = min(degree_map[u], degree_map[v]) - 1
            for i in range(degree_map[v], current_degree, -1):
                degree_map[i] = current_degree

    return covered_edges

