def calculate():
    h, L, v, P = parse()
    min_height = min(L)
    max_height = max(L)
    min_width = min(P)
    max_width = max(P)
    if h % 2 == v % 2:
        return "No"
    if v % 2 == 1:
        return "No"
    if min_height < min_width or max_height < max_width:
        return "No"
    lines = []
    for i in range(h + 1):
        if i % 2 == 0:
            lines.append((i // 2, min_width))
        else:
            lines.append((i // 2, max_width))
    x = sum(L)
    y = sum(P)
    for i in range(v):
        if i % 2 == 0:
            yield (x, -y + P[i])
        else:
            yield (x, y + P[i])
    for i in range(1, h + 1):
        if i % 2 == 0:
            yield (2 * (i // 2 - 1) - x, -y + P[i - 1])
        else:
            yield (2 * (i // 2 - 1) - x, y + P[i - 1])
    n = h + v + 2
    for j in range(n):
