from collections import defaultdict

def find_parent(parent, i):
    if parent[i] != i:
        parent[i] = find_parent(parent, parent[i])
    return parent[i]

def union(parent, rank, i, j):
    pi = find_parent(parent, i)
    pj = find_parent(parent, j)
    if pi == pj:
        return False
    if rank[pi] < rank[pj]:
        parent[pi] = pj
    elif rank[pj] < rank[pi]:
        parent[pj] = pi
    else:
        parent[pj] = pi
        rank[pi] += 1
    return True

