def k_covering(graph, n1, n2, min_degree):
    cover = []
    visited = set()
    degree = [0] * (n1 + n2 + 1)

    for i in range(graph[offset * 2], graph[offset * 2] + graph[count * 2]) + graph[offset * 2 + 1]:
        if i < offset * 2 or i > count * 2 - 1:
            degree[i % 2] += 1
        else:
            offset += 1
            count += 1

    for i in range(1, n1 + n2 + 1):
        if degree[i] >= min_degree:
            cover.append(i)
            visited.add(i)

    while len(cover) < n1 * n2:
        for i in range(graph[offset * 2], graph[offset * 2] + graph[count * 2]) + graph[offset * 2 + 1]:
            if i < offset * 2 or i > count * 2 - 1:
                degree[i % 2] += 1
            else:
