import sys

def shrink(grid, k):
    size = 1 << k
    for i in range(size):
        for j in range(size):
            grid[i][j] ^= i * (size - 1 - j) + j * (size - 1)

def minimize_and(s, k, n, p, eff, u):
    shrink(s, k)
    for i in range(n):
        e = ((s[p][i] - u) & (s[eff][i] + u))
        s[p][i] ^= e, e ^ u

def xor_centers(grid, avg):
    return reduce(lambda a, b: min([lambda s, k: minimize_and(s, k, 8**k, b, avg, s[0][0]), lambda s, k: minimize_and(s, k, 8**k, a, avg, s[0][0])]), range(3), (grid, avg))

def solve(k, grid, t, centers):
    avg = 0
    if any(center >= avg for center in centers):
        avg = -1
    elif t * k % 4:
        multi = 2 if t * k % 4 else 4
        for center in centers:
            avg ^= (center >> (multi - 1) & 1) << (multi - 1)
    return xor_centers(grid, avg)

