from collections import defaultdict

def path_to_tree(d, start, end, seen):
    if start == end:
        return (start,)
    if not d[start]:
        return None
    for tree, tree_tail in d[start]:
        if tree not in seen:
            seen.add(tree)
            next_path = path_to_tree(d, tree, end, seen.copy())
            if next_path is None:
                continue
            else:
                # prune longer path than or equal
                if len(next_path) == 1 or len(next_path) > len(next_path.tail):
                    return next_path
    return None

