import java.util.*;

public class Solution {
    static class Point implements Comparable<Point> {
        int a, b, s, q;

        Point(int a, int b, int s, int q) {
            this.a = a;
            this.b = b;
            this.s = s;
            this.q = q;
        }

        @Override
        public int compareTo(Point other) {
            if (this.s == other.s) return Integer.compare(this.a, other.a);
            return Integer.compare(this.s, other.s);
        }
    }

    static Map<Integer, Point> cats = new HashMap<>();
    static Map<Integer, Point> rats = new HashMap<>();

