import numpy as np
from io import StringIO

def get_next_field(field):
    return np.flip(field, axis=1) + (2**16 - field) % (2**16)

def calculate_submatrix_sum(n, m, field, time, query):
    t = time + query[3] - query[1]
    matrix = np.zeros((2*m, 2*n))
    for row in range(m):
        matrix[row,:] = field[row,:] + (2**16 - field[row,:]) % (2**16) if row > t else field[row,:]
    for row in range(n-m+1, 2*n):
        matrix[row,:] = get_next_field(field[0:row+1])
    for row in range(time, time+2*m-n):
        matrix[row,:] = np.flip(np.flip(field[0:row+1], axis=1) + (2**16 - field[0:row+1]) % (2**16), axis=0) % (2**16)
    return np.sum(matrix[int(query[0])-1: int(query[2])-1, int(query[1])-1:int(query[3])-1])

