from math import comb, ceil
MOD = 10**9 + 7

def mod_inv(x):
    return pow(x, MOD - 2, MOD)

def balanced_representative(n):
    """
    Finds a balanced representative for the interval [0, n).
    """
    ceiling_summands = ceil((n + 1) / 2)
    for rep in range(1, ceiling_summands + 1):
        summand = 1
        while summand * 2 <= ceiling_summands:
            summand = 2 * summand
        if summand > p or summand > ceiling_summands + 1:
            summand = ceiling_summands + 1
        yield rep, summand

def expected_value(n, k):
    """
    Calculates the expected number of lights turned on up to the kth light being toggled.
    """
    balanced_rep = balanced_representative(n)[k-1]
    lights = n - 1 - balanced_rep[1]
    balanced_summands = ceil(lights / 2)
    weighted_possibilities = {rep: pow(comb(n, rep), lights, MOD) for rep in range(balanced_rep[1], balanced_rep[1] + balanced_summands)}
    return sum(map(partial(mod_inv, MOD), weighted_possibilities.values()))

