    import heapq
    from math import inf

    diff_sum = 0
    max_times = 0
    link_stadiums = [[-inf for _ in range(k + 1)] for _ in range(n)]

    for i in range(n):
        for j in range(k):
            if i in games:
                link_stadiums[i][j] = ws[i]
                diff_sum += ws[i]
                max_times = max(max_times, link_stadiums[i][j])

    if (diff_sum + max_times * k) <= m:
        answer = []
        for i in range(m):
            d = inf
            for j in range(k):
                if link_stadiums[i%n][j] < d:
                    d = link_stadiums[i%n][j]
            answer.append(d)
        return answer

    else:
        answer = []
        s = set(link_stadiums[i])
        for j in range(k):
            for i in games:
                link_stadiums[i][j] += ws[i] / (k - 1)
            max_times = max(max_times, max(link_stadiums[i]))
        for j in range(k):
            for i in range(n):
                link_stadiums[i][j] += ws[i] / k
            for i in games:
                link_stadiums[i][j] += ws[i] / k
            diff_sum += max_times - link_stadiums[i][j]
        if diff_sum + k * max_times <= m:
            answer = []
            for i in range(k - 1, -1, -1):
                if link_stadiums[i] == []:
                    continue
                for j in link_stadiums[i]:
                    heapq.heappush(answer, -j)
                    if -answer[0] > m // k + 1:
                        break
                    answer = heapq.nlargest(m + 1, answer)
            return [-el for el in answer][:m]
        else:
            return [-el for el in link_stadiums[i]]

