from collections import defaultdict

def minimum_steps_to_introduce_friends(n, m, friends_pairs):
    # Adjacency list for storing the connections among friends
    adj_list = defaultdict(set)
    for pair in friends_pairs:
        adj_list[pair[0]].add(pair[1])
        adj_list[pair[1]].add(pair[0])

    # Function to calculate the minimum steps
    def bfs():
        visited = [False] * (n + 1)
        queue = [i for i in range(1, n + 1) if adj_list[i] != set([i]) and not visited[i]]
        step = 0
        while queue:
            step += 1
            new_queue = []
            for friend in queue:
                new_friends = adj_list[friend] - set(cluster)
                for new_friend in new_friends:
                    if not visited[new_friend]:
                        visited[new_friend] = True
                        new_queue.append(new_friend)
            queue = new_queue
            if any(new_friends == set(cluster) for cluster in visited):
                return step
        return -1

    # Trying all possible cluster sizes up to n/2
    for cluster_size in range((n + 1) // 2, 0, -1):
        for start in range(1, n + 1):
            if (n - sum(1 for i in range(start, n + 1) if len(adj_list[i] & set(range(1, n + 1))) >= cluster_size) + 1) % 2 == 0:
                cluster = [[] for _ in range(cluster_size)]
                start_index = 0
                for end in range(start, n + 1, cluster_size):
                    if len(adj_list[end]) < cluster_size:
                        start_index = end
                        break
                new_queue = [start_index]
                for num in range(start_index + 1, n + 1, cluster_size):
                    for friend in adj_list[num] - set(new_queue):
                        cluster[new_queue.index(new_queue[-1])].append(friend)
                        new_queue.append(friend)
                    new_queue.remove(start_index)
                    start_index += cluster_size
                visited = [False] * (n + 1)
                new_queue = []
                for friend in new_queue:
                    new_friends = adj_list[friend] - set(visited)
                    for new_friend in new_friends:
                        if not visited[new_friend]:
                            visited[new_friend] = True
                            new_queue.append(new_friend)
                if all(visited[i] for i in range(1, n + 1)):
                    return bfs()
    return -1

n, m = map(int, input().split())
friends_pairs = [list(map(int, input().split())) for _ in range(m)]
