from collections import defaultdict

def find_k_covering(U, V, E, min_deg):
    degree_map = defaultdict(int)
    for u, v in E:
        degree_map[u - 1] += 1
        degree_map[v - 1] += 1
    minimal_edges = []
    neighbors = defaultdict(list)

    if min_deg:
        for u, v in E:
            if degree_map[u - 1] >= min_deg and degree_map[v - 1] >= min_deg:
                neighbors[u - 1].append(v - 1)
                neighbors[v - 1].append(u - 1)

    for u in U:
        if degree_map[u - 1] <= min_deg:
            for v in V:
                if v not in neighbors[u - 1]:
                    minimal_edges.append((u, v))

    return minimal_edges

U, V, E = map(int, input().split())
min_deg = int(input())

minimal_edges = find_k_covering(U, V, E, min_deg)

